type recLog struct{ f *os.File }        // facade owns the stdlib handle

func openRecLog(path string) (*recLog, error) {
	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open rec log: %w", err)
	}
	return &recLog{f: f}, nil
}

func (l *recLog) Close() error { return l.f.Close() }

