/*
#include <sensor.h>
*/
import "C"

type Sensor struct{ h *C.sensor_t }

func Open(path string) (*Sensor, error) {
	cpath := C.CString(path)
	defer C.free(unsafe.Pointer(cpath))
	h := C.sensor_open(cpath)
	if h == nil {
		return nil, errors.New("sensor_open failed")
	}
	return &Sensor{h: h}, nil
}
